  // La respuesta y cada error típico difieren al menos 3 % (el «casi» nunca es ambiguo).
  function N(id, sub, d, vars, prompt, answer, why, o) {
    o = o || {};
    if (o.mistakes) {
      var base = o.where, ms = o.mistakes;
      o.where = function (v) {
        if (base && !base(v)) return false;
        var vals = [answer(v)].concat(Object.keys(ms).map(function (key) { return ms[key](v); }));
        for (var i = 0; i < vals.length; i++) for (var j = i + 1; j < vals.length; j++) {
          if (!isFinite(vals[i]) || !isFinite(vals[j]) || Math.abs(vals[i] - vals[j]) <= 0.03 * Math.max(Math.abs(vals[i]), Math.abs(vals[j]))) return false;
        }
        return true;
      };
    }
    if (!o.unit) o.unit = UN;
    var q = K.N(id, sub, d, vars, prompt, answer, why, o);
    if (o.alt) q.alt = o.alt;
    return q;
  }
